script.code:
//Variables Externas
var TI = Ua.findNode("AGENT.OBJECTS.Simulation.Aquaculture.Tiempo_Cultivo");
var Pause = Ua.findNode("AGENT.OBJECTS.Simulation.Aquaculture.Pause_Time");

//Variables Internas
var Vmax=15552000;
var Vmin=0;

//Ejecuto Logica
if (TI.result.value>=Vmax){
	TI.result.assign({value: 0});
}
else{
	if(Pause.result.value!=true){
		TI.result.assign({value: TI.result.value+1});
	}	
}
